query TargetDrugs($targetId: String!) {
  target(ensemblId: $targetId) {
    id
    approvedSymbol
    approvedName
    drugAndClinicalCandidates {
      count
      rows {
        id
        maxClinicalStage
        drug { ...DrugFields }
        diseases { diseaseFromSource disease { id name } }
        clinicalReports { ...ReportFields }
      }
    }
  }
}

fragment DrugFields on Drug {
  id
  name
  drugType
  maximumClinicalStage
  description
  parentMolecule { id name }
  mechanismsOfAction {
    uniqueActionTypes
    uniqueTargetTypes
    rows {
      mechanismOfAction
      actionType
      targetName
      targets { id approvedSymbol }
      references { source ids urls }
    }
  }
  indications {
    count
    rows { id maxClinicalStage disease { id name } }
  }
}

fragment ReportFields on ClinicalReport {
  id
  type
  source
  provider
  origin
  clinicalStage
  phaseFromSource
  trialPhase
  trialOverallStatus
  year
  url
}
